package org.confluence.mod.common.data.gen.language;

import java.util.function.BiConsumer;

public class DialogsLanguageSubProvider implements LanguageSubProvider {
    private final BiConsumer<String, String> consumer;

    public DialogsLanguageSubProvider(BiConsumer<String, String> consumer, boolean isEn) {
        this.consumer = consumer;
        addTranslations(isEn);
    }

    @Override
    public void english() {
        // npc dialogs
        add("dialogs.confluence.angler.wakeup.0", "Thanks, I guess, for saving me or whatever. You'd be a great helper minion!");
        add("dialogs.confluence.angler.wakeup.1", "Wha? Who might you be? I totally wasn't just drowning or anything!");
        add("dialogs.confluence.angler.wakeup.2", "You saved me! You're awful nice, I could use you... er, I mean, totally hire you to do some awesome stuff for me!");
        add("dialogs.confluence.female_angler.0", "What a pity! Some fish may have disappeared even before I was born. I hope we can protect the remaining ones well~");
        add("dialogs.confluence.female_angler.1", "Ah... I'm so sorry! Did I disturb you while reeling in my line? I really apologize!");
        add("dialogs.confluence.female_angler.2", "Although there's no chef in the whole %s, being able to cook fish with my own hands is a kind of happiness!");
        add("dialogs.confluence.female_angler.3", "I don't have a mom or dad, but I have so many lovely fish to keep me company! I'm already very content~");
        add("dialogs.confluence.female_angler.4", "Take my advice, sweetie~ Never touch ice cubes with your tongue! You'll get frostbite, so make sure to take good care of yourself!");
        add("dialogs.confluence.female_angler.5", "Have you ever heard of fish that can make sounds? I think I've seen some before! Would you like to talk about it with me?");
        add("dialogs.confluence.female_angler.6", "Oh dear! Be careful~ I set up some little decorations, not traps! I just wanted to give everyone a small surprise, please don't misunderstand~");
        add("dialogs.confluence.female_angler.7", "The %s is full of lovely and unique fish everywhere! It's truly wonderful!");
        add("dialogs.confluence.female_angler.stat.0", "You know what? I've already collected %s beautiful fish! Thank you so much—I could never have done it without your help!");
        add("dialogs.confluence.female_angler.stat.1", "Oh no! I've bothered you %s times already, I'm so terribly sorry! But every time I get to see such beautiful fish, it makes me so happy!");
        add("dialogs.confluence.female_angler.wakeup.0", "Thank you so much! I really don't know how to repay you—you're an amazing friend!");
        add("dialogs.confluence.female_angler.wakeup.1", "Oh! It's you~ I just slipped a moment ago, I wasn't drowning! Thank you for caring so much!");
        add("dialogs.confluence.female_angler.wakeup.2", "Thank you for saving me! You're such a kind person~ If you don't mind, I'd like to ask you to help me with a small errand—but it's totally fine if you don't want to!");
        add("dialogs.confluence.female_angler.task_ready.0", "Hello there~ I have a tiny favor to ask. Could you help me if you're free? It's absolutely fine if you're not!");
        add("dialogs.confluence.female_angler.task_ready.1", "I'm looking for a special kind of fish. It would mean the world to me if you'd help find it! No rush at all—let's take our time to go over the details~");
        add("dialogs.confluence.female_angler.task_ready.2", "%1$s would like to formally invite you to become %2$s's fishing helper! Would you accept?");
        add("dialogs.confluence.female_angler.task_ready.3", "Hello! You must be the amazing fishing master I've been looking for! Could I ask for your help, please?");
        add("dialogs.confluence.female_angler.task_succeed.0", "Wow! Thank you for catching the fish I wanted—thank you so much! You must be tired, take it easy~");
        add("dialogs.confluence.female_angler.task_succeed.1", "You did an absolutely wonderful job! You've worked hard—go rest for a bit~");
        add("dialogs.confluence.female_angler.task_succeed.2", "I'm so happy! You finished safely, that's such a relief! I was worried about you the whole time!");
        add("dialogs.confluence.female_angler.task_succeed.3", "Oh my goodness! You not only completed the task but also came back safe and sound—you're incredible! Please hand me the fish, and go get some rest~");
        add("dialogs.confluence.female_angler.task_succeed.4", "We got it! Everything went perfectly~ Thank you for your help, I really appreciate it!");
        add("dialogs.confluence.female_angler.task_finished.0", "I have enough fish now! Thank you so much for all your help—you've done so much for me~");
        add("dialogs.confluence.female_angler.task_finished.1", "Thank you so much for today! I had such a lovely time with you! Go take care of your own things now~");
        add("dialogs.confluence.female_angler.task_finished.2", "I don't have any errands for you right now, but thank you so much for stopping by anyway~");
        add("dialogs.confluence.female_angler.task_finished.3", "I have enough fish for today—you've worked hard! Take care, and goodbye for now~");
        add("dialogs.confluence.female_angler.task_finished.4", "I still have the fish you gave me last time safely stored away. I don't need more for now, but thank you so much all the same!");
        add("dialogs.confluence.female_angler.task_finished.5", "Thank you so much! Having a helper like you is such a blessing to %s~");
        add("dialogs.confluence.angler.item.confluence.amanita_fungifin", "I found this spectacular place draped in giant glowing mushrooms! Everything was blue! I was picking some of the mushrooms I found next to a glistening blue lake, when one of the mushrooms snapped at me and swam away! I want to give it a taste of its own medicine, and give it a good chompin'! What I mean is, you gotta get it for me!(Caught in Glowing Mushroom Biomes)");
        add("dialogs.confluence.angler.item.confluence.angelfish", "Did you know there's magical islands that float up high in the sky? Bet you didn't! They say angels live in the sky, and I believe those angels have fins and gills and swim around! I believe you must catch one for me!(Caught in Sky Lakes)");
        add("dialogs.confluence.angler.item.confluence.batfish", "Na na na na na na na Bat-FISH! That means go digging underground, fetch it, and bring it to me!(Caught in Underground & Caverns)");
        add("dialogs.confluence.angler.item.confluence.bloody_manowar", "Ow! Don't get near me! I got stung by a Bloody Man-O-War! In case you're not smart enough to know what that is, it's the most menacing jellyfish in all of world ! Go to that rotten crimson and catch it if you dare! (Caught in Crimson)");
        add("dialogs.confluence.angler.item.confluence.bonefish", "Normally I could care less if I see fishbones floating in the water underground, but this one was swimming! What, you thought that only human skeletons still flailed about in world ? Get it for me so I can stick it in someone's bed!(Caught in Underground & Caverns)");
        add("dialogs.confluence.angler.item.confluence.bumblebee_tuna", "The subterranean jungles of world have the weirdest things! Like, there's this fish I saw that looked just like a giant bumblebee! I'm allergic to bees, so you have to catch it for me! I bet it'd taste like a tuna and honey sandwich!(Caught in Honey)");
        add("dialogs.confluence.angler.item.confluence.bunnyfish", "Out in the forest, I was fishing right? Well guess what! A bunny hopped up to me! Then another one hopped up, and another... suddenly I'm surrounded by bunnies! One even swam up to me from the water, but it had no legs! I fell outta my chair in surprise and all the bunnies scurried off! I want that bunny fish as a pet, so you better catch it for me! Pronto!(Caught in Surface)");
        add("dialogs.confluence.angler.item.confluence.capn_tunabeard", "Yarr matey! Shiver me timbers! Avast, scallywags! There's a pirate captain who once had a pet fish named Cap'n Tunabeard, but during a big storm the fishbowl fell overboard! It has a hook for a tail, and an eyepatch and everything! You need to fetch me that fish, so I can be as cool as a pirate! Obviously it's out in the ocean somewhere! Duh!(Caught in Ocean)");
        add("dialogs.confluence.angler.item.confluence.catfish", "I finally found a jungle cat that likes water! I think it's because it's also part fish. I don't know why this happened, and I don't want to know. I just want it in my hands, and make it snappy!(Caught in Jungle Surface)");
        add("dialogs.confluence.angler.item.confluence.cloudfish", "There's a rumor going around that there are islands that float high up in the sky, and that they have amazing treasure! Who cares about that though, what's even cooler is that sometimes lakes form in the clouds, and in those lakes are fish made out of clouds! I wanna know what it tastes like, so you better go catch it for me!(Caught in Sky Lakes)");
        add("dialogs.confluence.angler.item.confluence.clownfish", "I saw this bright orange and colorful fish by the ocean, and it was looking around frantically as though it was seeking a lost family member! Go catch it for me, so that another one will show up looking frantically for him instead!(Caught in Ocean)");
        add("dialogs.confluence.angler.item.confluence.cursedfish", "There's a cursed fish swimming in the waters of the deepest corruption! It was forged of the cursed flames that spread from the fallen horrors that lurk down there. They say not even water can put out this fire, and that it can burn forever. I can think of some awesome things I can do with a fish like that! You gonna go get it for me, or are you too chicken!?(Caught in Corruption)");
        add("dialogs.confluence.angler.item.confluence.demonic_hellfish", "I hear in the underworld, that the King of all demons is actually a fish! Just imagine the absolute power I would have if you caught it for me!(Caught in Caverns)");
        add("dialogs.confluence.angler.item.confluence.derpfish", "Those Derplings in the jungle are the most scary creatures I've ever seen! Good thing is, sometimes they don't have legs! These ones live in the water and are a lot less scary! Catch me one now so I can see what they taste like without being scared half to death!(Caught in Jungle Surface)");
        add("dialogs.confluence.angler.item.confluence.dirtfish", "I was reeling in the big one when this funny talking zombie burst out of the forest lake and started rambling on about this 'ferocious' species of fish made out of dirt! He says it could suffocate ten blokes his size, or something like that... I want it! NOW!(Caught in Surface & Underground)");
        add("dialogs.confluence.angler.item.confluence.dynamite_fish", "The demolitionist was raising cane about losing a stick of dynamite in the lake out in the forest. He has like, so many, so why does one matter? Apparently, because it grew fins and started swimming away! I don't know where he gets his materials to make those things, but that one is clearly possessed! Reel it in and bring it to me, I always wanted a suicide bombing fish! Don't ask why...(Caught in Surface)");
        add("dialogs.confluence.angler.item.confluence.eater_of_plankton", "I bet you're not brave enough to find the Eater of Plankton. A corrupt fish that was mutated from a severed piece of the Eater of Worlds itself! Capture it and bring it to me, and prove to me you're not a wuss!(Caught in Corruption)");
        add("dialogs.confluence.angler.item.confluence.fallen_starfish", "I love collecting those bright yellow stars that fall from the sky! I love it even more when they land on someone's head. But.. but.. nothing beats a star that falls in a foresty lake and turns into a fish! That's just totally rad, and you're just rad enough to get it for me!(Caught in Sky Lakes & Surface)");
        add("dialogs.confluence.angler.item.confluence.the_fish_of_cthulhu", "Apparently, Demon Eyes can sometimes be amphibious. They don't fly, they swim! I want to see the look on someone's face when they find it in their bathtub! They hang around the same areas. That means you reel one in for me!(Caught in Sky Lakes & Surface)");
        add("dialogs.confluence.angler.item.confluence.fishotron", "I don't know what's worse, a bone fish or a bone fish with HANDS. This Fish-o-Tron deep in the caverns really freaks me out! I think it's possessed by the same evil spirits that possessed that old man by the dungeon! I double duck dare you to go catch it!(Caught in Caverns)");
        add("dialogs.confluence.angler.item.confluence.fishron", "There's a legend of a mighty being known as the Fishron! It's part pig, part dragon, and part FISH! I hear it hangs around in the frozen subterranean lakes of the coldest part of the world! I'm not going there, so YOU go catch it and makes sure it lands in my hands! I'm so excited!(Caught in Underground Tundra)");
        add("dialogs.confluence.angler.item.confluence.guide_voodoo_fish", "Those demons in the underworld really like voodoo dolls, but I think there's a doll out there who was blasted with way too much magic! It turned into a fish and it does stuff on its own. I dare you to go down and get me one! I'd watch out for the boiling lava, because it burns you to death and that won't get me my fish!(Caught in Caverns)");
        add("dialogs.confluence.angler.item.confluence.harpyfish", "I was trying to sleep by the hill lakeside when this fish swooped down at me. It was flying! It also had the face of a lady and had feathers! I think I screamed louder than she did! Hey you, go make her pay for scaring me like that!(Caught in Sky Lakes & Surface)");
        add("dialogs.confluence.angler.item.confluence.hungerfish", "There's a piece of the Hunger that morphed from the Wall of Flesh into a small fish-like thing that swims around aimlessly in the underworld and it's gross and it's yucky and I want it now!(Caught in Caverns)");
        add("dialogs.confluence.angler.item.confluence.ichorfish", "Did you know deep in the crimson, some of those creatures make this gross yellow stuff? I overheard a crazy story about a pool of it having melted together into a shape of a fish and it swims around and everything! Fetch it for me, so I can stick it in someone's toilet!(Caught in Crimson)");
        add("dialogs.confluence.angler.item.confluence.infected_scabbardfish", "A really long fish that looks like a sword's sheath swims in the murky waters of the corruption! It looks a lot like ebonstone, so don't let it fool you! That's right, you. You're catching it, not me!(Caught in Corruption)");
        add("dialogs.confluence.angler.item.confluence.jewelfish", "Oooooohhh, I'm going to be SO rich! Deep in the caverns, there is a fish made out of gemstones! Don't ask me how, I don't know, all I know is that this fish is totally awesome and you're going to catch it for me!(Caught in Underground & Caverns)");
        add("dialogs.confluence.angler.item.confluence.mirage_fish", "There's some interesting critters to be found in the deeper Hallows, I tell you! They glow this crazy purple color and it messes with my eyes! It's totally wild, so I want you to catch a fish like that for me!(Caught in Underground Hallow)");
        add("dialogs.confluence.angler.item.confluence.mudfish", "Watch your step when wading through jungle waters! Why? No, not because I care about you being eaten by piranhas. I care because you'll step on one of my favorite kinds of fish, the Mud Fish! I also care a lot that you're going to grab me one as a pet!(Caught in Jungle)");
        add("dialogs.confluence.angler.item.confluence.mutant_flinxfin", "What's white and tan and fluffy and lives in a frozen underground lake? A mutant flinxfin! I wasn't telling a joke, you know, there really is a mutated variety of Flinx that is more adapted to an aquatic lifestyle! I want it to adapt to my fishbowl, so make sure that happens!(Caught in Underground Tundra)");
        add("dialogs.confluence.angler.item.confluence.pengfish", "It's a whale! It's a dolphin! No, it's a penguin fish! Oh, and look, it's you! You get to bring me one! You do know they only like cold water, right?(Caught in Surface Tundra)");
        add("dialogs.confluence.angler.item.confluence.pixiefish", "There's a really really rare type of pixie that's born with so many wings that it can't actually fly! It swims with the fishes in the lakes surrounded by that blue colored grass. My fish tank needs a lamp, so I want you to catch me that pixie!(Caught in Surface Hallow)");
        add("dialogs.confluence.angler.item.confluence.scarab_fish", "I read this ancient story about a fish that looks like a magical scarab! That's beetle, for simpletons like you! Where do you find it? Where do you think? In the desert, duh! Don't look at me like that... it's true! There is actually water out there! I'd go, but I don't like having my eyeballs pecked out by vultures. So... you do it!(Caught in Desert)");
        add("dialogs.confluence.angler.item.confluence.scorpio_fish", "I'm sure someone, a really stupid someone, tried to tell you there was no water in the desert! They were absolutely and positively wrong! There's this thing called an Oasis, and it has water in it! Guess what happens when you have water!? That's right, you have fish! Weird fish that try to sting you and pinch you and do all kinds of other mean things to you! A perfect pet for me, and a perfect job for you!(Caught in Desert)");
        add("dialogs.confluence.angler.item.confluence.slimefish", "In the forest, the slimes are kinda gross. Slimefish are even more so! I don't want to swim with slimes, so yoink one out of the water for me!(Caught in Surface Forest)");
        add("dialogs.confluence.angler.item.confluence.spiderfish", "I saw a fish that had eight legs! Nope! Not happening! You're fishing it for me, so it's not alive when I hold it! That's the last time I go fishing so deep in the cavern!(Caught in Underground & Caverns)");
        add("dialogs.confluence.angler.item.confluence.tropical_barracuda", "Piranhas and sharks are ugly! Soooo ugly! Did you know there's a fish that looks very pretty and still can eat your face off? I would pay 2 platinum to see that happen, by the way... To the point, though, you catchy for me. Just make sure I have it before you lose your face!(Caught Jungle Surface)");
        add("dialogs.confluence.angler.item.confluence.tundra_trout", "You ever wonder why the lakes on the surface of the snowy areas of world never ice over? I don't. The fish, however, do! A fish made out of ice would make a great offering to the mighty and amazing Angler ! Go, my loyal subject, and bring me this Tundra Trout with haste!(Caught in Surface Tundra)");
        add("dialogs.confluence.angler.item.confluence.unicorn_fish", "Unicorns and rainbows are absolutely great! They're everywhere, even in the water. No, really, I actually saw a unicorn fish in the Hallowed lake! Your job is to reel it up and let me have it as a pet!(Caught in Hallow)");
        add("dialogs.confluence.angler.item.confluence.wyverntail", "I know something youuuuu don't! Fine, I'll tell you, there's a terrifying creature that flies among the stars! I'm not making this up! It's called a Wyvern! But, but, you knew that already, right? Well what you don't know is that they are born and raised as tadpoles! So, they're actually like.. well, a frog! Hop to it and get me one!(Caught in Sky Lakes)");
        add("dialogs.confluence.angler.item.confluence.zombie_fish", "You won't believe it! I caught a fish in the forest at night that was already dead! Then it tried to eat me! I threw it away and ran! Now I want to stick it in someone's dresser to see what happens, so go fish it back up for me will ya?!(Caught in Surface)");

        add("dialogs.confluence.guide.0", "My job is to offer suggestions for your upcoming tasks. I recommend that you come and talk to me whenever you encounter any difficulties.");
        add("dialogs.confluence.guide.1", "They said there would be someone to tell you how to survive in this place... Oh, wait a moment. That person is me.");
        add("dialogs.confluence.guide.2", "You should stay at home at night. It's very dangerous to wander outside in the dark.");
        add("dialogs.confluence.guide.3", "In the Confluence world, you will obtain multiple times the treasure, but this also means taking on multiple times the risk.");
        add("dialogs.confluence.guide.4", "As far as I know, there are more humans in this world than in our original world.");
        add("dialogs.confluence.guide.5", "Sorry, sometimes I have to open the door.");
        add("dialogs.confluence.guide.6", "Those guys that can explode are more threatening than the average surface monsters!");
        add("dialogs.confluence.guide.7", "The life mushrooms on the grass can sometimes save your life.");
        add("dialogs.confluence.guide.8", "There are Crystal Hearts underground, which can be used to increase your maximum health. You can use a pickaxe to break them.");
        add("dialogs.confluence.guide.9", "There is a lake with magical powers underground, and it's very rare.");
        add("dialogs.confluence.guide.10", "At night, stars are falling and spreading all over the world. They have extremely wide uses. If you see them, you must get them, because the stars will disappear after sunrise.");
        add("dialogs.confluence.nurse.0", "I need to have a serious talk with the Guide. How many times a week do you get severely burned by lava exactly?");
        add("dialogs.confluence.nurse.1", "See that old man wandering around the dungeon? He looks like he's in trouble.");
        add("dialogs.confluence.nurse.2", "Hey, has the Arms Dealer ever mentioned going to see a doctor or something? Just asking.");
        add("dialogs.confluence.nurse.3", "Got into trouble with the thugs again?");
        add("dialogs.confluence.nurse.4", "Don't be such a child! I've seen worse.");
        add("dialogs.confluence.nurse.5", "Did it hurt when you did that? Don't do that.");
        add("dialogs.confluence.demolitionist.0", "Explosives are really popular nowadays. Buy some right away!");
        add("dialogs.confluence.demolitionist.1", "Today is a great day to court death!");
        add("dialogs.confluence.demolitionist.2", "Let me see what happens if I do this... (BOOM!)... Oh, sorry, did you still need that leg?");
        add("dialogs.confluence.demolitionist.3", "Take a look at my goods; they're all at amazing prices.");
        add("dialogs.confluence.demolitionist.4", "Dynamite, this is my special panacea prepared just for you. It can cure all kinds of problems.");
        add("dialogs.confluence.demolitionist.5", "Want to get through those evil stones, huh? Why not just blow them up with explosives!");
        add("dialogs.confluence.goblin_tinkerer.0", "Goblins get angry so easily. In fact, they can start a war over some rags!");
        add("dialogs.confluence.goblin_tinkerer.1", "To be honest, most goblins aren't real rocket scientists. Well, some of them are.");
        add("dialogs.confluence.goblin_tinkerer.2", "Do you know why everyone carries these spiky balls around? Because I don't.");
        add("dialogs.confluence.goblin_tinkerer.3", "I've just finished my latest creation! This version won't explode violently even if you blow or suck on it really hard.");
        add("dialogs.confluence.goblin_tinkerer.4", "Goblin thieves aren't very good at stealing. They can't even steal from an unlocked chest!");
        add("dialogs.confluence.goblin_tinkerer.5", "Yo, I heard you like rockets and running shoes, so I added some rockets to your running shoes.");
        add("dialogs.confluence.arms_dealer.0", "Dude, get your hands off my gun!");
        add("dialogs.confluence.arms_dealer.1", "Hey, bro, this isn't a movie. You need to prepare ammunition separately.");
        add("dialogs.confluence.arms_dealer.2", "I see you're eyeing the Minishark... You can't even imagine how it's made.");
        add("dialogs.confluence.arms_dealer.3", "I want to buy something from the Nurse. What did you say? She doesn't sell anything?");
        add("dialogs.confluence.arms_dealer.4", "Flying Fish? I call it target practice!");
        add("dialogs.confluence.arms_dealer.5", "Don't waste your time with the Demolitionist. I've got everything you need right here.");
        add("dialogs.confluence.merchant.0", "Swords beat paper! Buy one right away.");
        add("dialogs.confluence.merchant.1", "Do you want apples? Do you want carrots? Do you want pineapples? All we have are torches.");
        add("dialogs.confluence.merchant.2", "Take a look at my dirt blocks; they're really earthy.");
        add("dialogs.confluence.merchant.3", "You have no idea how much dirt blocks can sell for in other places.");
        add("dialogs.confluence.merchant.4", "One day they will tell your legend... It's sure to be a good story.");
        add("dialogs.confluence.merchant.5", "Kosh, kapleck Mog. Oh, sorry, that's Klingon, which means 'Buy or die.'");
        add("dialogs.confluence.painter.0", "I know the difference between turquoise and teal. But I'm not going to tell you.");
        add("dialogs.confluence.painter.1", "The titanium white is all used up. Don't ask.");
        add("dialogs.confluence.painter.2", "Try mixing pink and purple. It'll definitely work, I swear!");
        add("dialogs.confluence.painter.3", "No, no, no... There are many kinds of gray! Don't make me start...");
        add("dialogs.confluence.painter.4", "I hope it stops raining. The paint still hasn't dried. It would be a disaster if it rains!");
        add("dialogs.confluence.painter.5", "I tried organizing a paintball war, but everyone just wanted food and decorations.");
        add("dialogs.confluence.dryad.0", "Stay safe! Both worlds need you!");
        add("dialogs.confluence.dryad.1", "The hourglass of time is slowly running out. And you're not aging gracefully.");
        add("dialogs.confluence.dryad.2", "Two goblins walked into a bar, and one of them said to the other: 'A glass of beer?'");
        add("dialogs.confluence.dryad.3", "What does it mean by saying I'm all talk and no action?");
        add("dialogs.confluence.dryad.4", "You must stop the spread of evil.");
        add("dialogs.confluence.dryad.5", "This world is much vaster... And the power of nature is stronger too.");
        add("dialogs.confluence.dye_trader.0", "I bring you the richest colors in exchange for your wealth.");
        add("dialogs.confluence.dye_trader.1", "Honey, your clothes are so monotonous. You really have to learn how to dye your dull clothes!");
        add("dialogs.confluence.dye_trader.2", "The only wood I'm willing to dye is mahogany. Dyeing any other wood is a waste.");
        add("dialogs.confluence.dye_trader.3", "Oh, no, no, that won't do. Even if you have money, you have to trade me with rare plant samples!");
        add("dialogs.confluence.dye_trader.4", "These dye bottles? Sorry, my dear friend, these are not for sale. I only accept the rarest plants in exchange for them!");
        add("dialogs.confluence.dye_trader.5", "You think you can fool my eyes? I don't think so! I only accept the rarest flowers in exchange for these special bottles.");
        add("dialogs.confluence.angler.0", "I'm bummed out! There's probably been fish that have gone extinct before I even was born, and that's not fair!");
        add("dialogs.confluence.angler.1", "Whaaaat?! Can't you see I'm winding up fishing line??");
        add("dialogs.confluence.angler.2", "There's no chefs in all of %s, so I have to cook all this fish myself! ");
        add("dialogs.confluence.angler.3", "I don't have a mommy or a daddy, but I have a lot of fish! It's close enough!");
        add("dialogs.confluence.angler.4", "Let a kid give you some advice, never touch your tongue to an ice block! Wait, forget what I said, I totally want to see you do it!");
        add("dialogs.confluence.angler.5", "Ever heard of a barking fish?! I haven't, I'm just wondering if you did!");
        add("dialogs.confluence.old_man.0", "I cannot let you enter until you free me of my curse.");
        add("dialogs.confluence.old_man.1", "Stranger, do you possess the strength to defeat my master?");
        add("dialogs.confluence.old_man.2", "Defeat my master, and I will grant you passage into the Dungeon.。");
        add("dialogs.confluence.old_man.3", "Come back at night if you wish to enter.");
        add("dialogs.confluence.traveling_merchant.0", "Hmm, you look like you could use an Angel Statue! They slice, and dice, and make everything nice!");
        add("dialogs.confluence.traveling_merchant.1", "I don't refund for \"buyer's remorse...\" Or for any other reason, really.");
        add("dialogs.confluence.traveling_merchant.2", "Buy now and get free shipping!");
        add("dialogs.confluence.traveling_merchant.3", "I sell wares from places that might not even exist!");
        add("dialogs.confluence.traveling_merchant.4", "You want two penny farthings!? Make it one and we have a deal.");
        add("dialogs.confluence.traveling_merchant.5", "Combination hookah and coffee maker! Also makes julienne fries!");
        add("dialogs.confluence.traveling_merchant.6", "Come and have a look! One pound fish! Very, very good! One pound fish!");
        add("dialogs.confluence.traveling_merchant.7", "If you're looking for junk, you've come to the wrong place.");
        add("dialogs.confluence.traveling_merchant.8", "A thrift shop?  No, I am only selling the highest quality items on the market.");
        add("dialogs.confluence.mechanic.0", "Did you make sure your device was plugged in?");
        add("dialogs.confluence.mechanic.1", "Oh, you know what this house needs? More blinking lights.");
        add("dialogs.confluence.mechanic.2", "DON'T MOVE. I DROPPED MY CONTACT.");
        add("dialogs.confluence.mechanic.3", "Thank you! Sooner or later, I'll end up like the other skeletons in the dungeon.");
        add("dialogs.confluence.mechanic.4", "I don't quite remember what happened in there. Three, maybe four important things...");
        add("dialogs.confluence.mechanic.5", "Oh yes, the Signal Adapter! It can connect the redstone here to the wires perfectly.");
        add("dialogs.confluence.witch_doctor.0", "Which doctor am I? The Witch Doctor am I.");
        add("dialogs.confluence.witch_doctor.1", "Choose wisely, my commodities are volatile and my dark arts, mysterious.");
        add("dialogs.confluence.witch_doctor.2", "The heart of magic is nature. The nature of hearts is magic.");
        add("dialogs.confluence.witch_doctor.3", "I sense a kindred spirit in the Etherian Dark Mages. A pity they are our enemies, I would have liked to learn from them.");
        add("dialogs.confluence.clothier.0", "Thanks again for freeing me from my curse. Felt like something jumped up and bit me.");
        add("dialogs.confluence.clothier.1", "Mama always said I would make a great tailor.");
        add("dialogs.confluence.clothier.2", "Life's like a box of clothes; you never know what you are gonna wear!");
        add("dialogs.confluence.clothier.3", "Of course embroidery is hard! If it wasn't hard, no one would do it! That's what makes it great.");
        add("dialogs.confluence.clothier.4", "I know everything they is to know about the clothierin' business.");
        add("dialogs.confluence.clothier.5", "Being cursed was lonely, so I once made a friend out of leather. I named him Wilson.");
        add("dialogs.confluence.clothier.6", "I keep having vague memories of tying up a woman and throwing her in a dungeon.");
        add("dialogs.confluence.party_girl.0", "We have to talk. It's... it's about parties.");
        add("dialogs.confluence.party_girl.1", "I can't decide what I like more: parties, or after-parties.");
        add("dialogs.confluence.party_girl.2", "We should set up a blinkroot party, and we should also set up an after-party.");
        add("dialogs.confluence.party_girl.3", "Put up a disco ball and then I'll show you how to party.");
        add("dialogs.confluence.party_girl.4", "I went to Sweden once, they party hard, why aren't you like that?");
        add("dialogs.confluence.party_girl.5", "My name's Party Girl but people call me party pooper. Yeah I don't know, it sounds cool though.");
        add("dialogs.confluence.party_girl.6", "Do you party? Sometimes? Hm, okay then we can talk...");
        add("dialogs.confluence.truffle.0", "As if living underground wasn't bad enough, jerks like you come in while I'm sleeping and steal my children.");
        add("dialogs.confluence.truffle.1", "I tried to lick myself the other day to see what the big deal was, everything started glowing blue.");
        add("dialogs.confluence.truffle.2", "Everytime I see the color blue, it makes me depressed and lazy.");
        add("dialogs.confluence.truffle.3", "You haven't seen any pigs around here have you? My brother lost his leg to one.");
        add("dialogs.confluence.truffle.4", "I don't know the 'Truffle Shuffle,' so stop asking!");
        add("dialogs.confluence.truffle.5", "There's been such a huge rumor that's being spread about me, 'If you can't beat him, eat him!'");
        add("dialogs.confluence.truffle.6", "I feel there are more of my kind here...");
        add("dialogs.confluence.guide.jei_check", "In Minecraft, I can't help you look up recipes, but I know a mod called JEI that can help you.");
        add("dialogs.confluence.nurse.player_killed_by", "Have you been killed %2$s times by %1$s? I'm curious who took your flag");

        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.0", "Again! Let's chop another!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.1", "This is AWESOME!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.2", "Die! Die!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.3", "This is what I live for!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.4", "Stupid tree!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.5", "I feel ALIVE!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.6", "We did it!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.7", "HaHAHA!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.8", "Woooooo!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.9", "YEEEESS!");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_gem_tree.0", "So, stone trees... what's up with that?");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_cactus.0", "When you think about it, cacti are just prickly trees!");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.0", "This sucks.");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.1", "It's dark in here!");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.2", "Help! Get me out!");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.3", "There's nothing to chop in here!");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.4", "I'm claustrophobic!");
        add("dialogs.confluence.lucy_the_axe.placed_back_into_the_inventory.0", "Oh, thank goodness!");
        add("dialogs.confluence.lucy_the_axe.placed_back_into_the_inventory.1", "From now on we'll be inseparable.");
        add("dialogs.confluence.lucy_the_axe.placed_back_into_the_inventory.2", "Ahh, I'm back where I belong.");
        add("dialogs.confluence.lucy_the_axe.idle.0", "Hey! Chop some trees!");
        add("dialogs.confluence.lucy_the_axe.idle.1", "This is perfect chopping weather.");
        add("dialogs.confluence.lucy_the_axe.idle.2", "Chop chop chop. Heh.");
        add("dialogs.confluence.lucy_the_axe.idle.3", "We make a good team!");
        add("dialogs.confluence.lucy_the_axe.idle.4", "Let's find a small grove and just go nuts!");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.0", "You'll come back, right?");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.1", "Hey! I'd never throw you away!");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.2", "Don't forget about me!");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.3", "Aren't we friends?");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.4", "You're abandoning me?!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.0", "Knock it off!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.1", "Rude!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.2", "I am an axe possessed!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.3", "Pick on someone your own size!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.4", "Hey!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.5", "Ouch, that hurts.");
        add("dialogs.confluence.lucy_the_axe.attack_entity.6", "Get rid of them! It's freaking me out.");
        add("dialogs.confluence.lucy_the_axe.attack_entity.7", "This is what I live for!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.8", "Woo-hoohoo!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.9", "RAAAA!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.10", "Die! Die!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.11", "Nice swing!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.12", "This is AWESOME!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.13", "We make a good team!");
        add("dialogs.confluence.lucy_the_axe.attack_entity.14", "Leave me alone, you brute!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.0", "OH YES!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.1", "So juicy!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.2", "A satisfying mea!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.3", "Worthy!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.4", "Beautiful!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.5", "A delight!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.6", "I am satiated!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.7", "Gluttonous!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.8", "I'm proud of us!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.9", "That's it?");
        add("dialogs.confluence.lucy_the_axe.kill_entity.10", "AXE-IMUM POWER!!!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.11", "Too easy!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.12", "This is AWESOME!");
        add("dialogs.confluence.lucy_the_axe.kill_entity.13", "You're a HACK!");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.0", "I'm rather insulted.");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.1", "This sucks.");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.2", "I prefer the tree-y variety.");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.3", "you've changed!");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.4", "Remember how much fun we had chopping trees?");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.5", "Hey! Chop some trees!");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.6", "All work and no play makes me want to chop some trees.");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.7", "Do you know what chop means?");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.8", "There's nothing to chop in here!");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.9", "This is honestly the worst.");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.10", "I'm getting dirty!");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.11", "How dare you do this to me!");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.12", "Ooo I'll remember that!");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.13", "You don't have to do this!");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.14", "Are you sure you're feeling alright?");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.15", "You're looking extra gruff today.");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.16", "You're overdoing it!");

        add("dialogs.confluence.wizard.0", "Want me to pull a coin from behind your ear? No? Ok.");
        add("dialogs.confluence.wizard.1", "Do you want some magic candy? No? Ok.");
        add("dialogs.confluence.wizard.2", "I make a rather enchanting hot chocolate if you'd be inter...No? Ok.");
        add("dialogs.confluence.wizard.3", "Are you here for a peek at my crystal ball?");
        add("dialogs.confluence.wizard.4", "Ever wanted an enchanted ring that turns rocks into slimes? Well neither did I.");
        add("dialogs.confluence.wizard.5", "Someone once told me friendship is magic. That's ridiculous. You can't turn people into frogs with friendship.");
        add("dialogs.confluence.wizard.6", "I can see your future now... You will buy a lot of items from me!");
        add("dialogs.confluence.wizard.7", "I once tried to bring an Angel Statue to life. It didn't do anything.");
        add("dialogs.confluence.zoologist.0", "I collected critters like you once, then I took a cursed fox bite to the knee!");
        add("dialogs.confluence.zoologist.1", "I may not know, like, a whole lot...but I can talk your head off about nature and critters and animals and wildlife and...");
        add("dialogs.confluence.zoologist.2", "My older bro calls me a lycanthrope. It means I'm like, part animal or something. He'd know, though, because he spends all his time outside!");
        add("dialogs.confluence.zoologist.3", "I love animals, like, a lot! I tried to pet this weird looking fox one time, he sooo bit me, and now I became like one! Rad!");
        add("dialogs.confluence.zoologist.4", "Staahp pulling on my tail, bro, it's totally real, and like...totally hurts when you pull on it!");
        add("dialogs.confluence.zoologist.5", "Oh, THESE ears? Haha, totes better to hear you with, my dear!");
        add("dialogs.confluence.zoologist.6", "This one time, at critter camp, I woke up one morning and everything was torn apart! Like, wow, how did I sleep through THAT?!");
        add("dialogs.confluence.zoologist.7", "Wow, like, I've never seen a full moon. For some reason, it's like I pass out every time one's around!");
        add("dialogs.confluence.zoologist.8", "I have noooo idea how I got here, but it's mega rad.");
        add("dialogs.confluence.stylist.0", "Your hair is fine, but I can make it fabulous.");
        add("dialogs.confluence.stylist.1", "A fresh style can make even an adventurer look civilized.");
        add("dialogs.confluence.stylist.2", "Sit still. Great hair takes precision.");
        add("dialogs.confluence.tax_collector.0", "Taxes are due. I assure you, every coin is accounted for.");
        add("dialogs.confluence.tax_collector.1", "Running a town is expensive. Fortunately, everyone else pays for it.");
        add("dialogs.confluence.tax_collector.2", "Another day, another ledger full of overdue payments.");
    }

    @Override
    public void chinese() {
        // npc对话
        add("dialogs.confluence.angler.wakeup.0", "谢谢，我想，谢谢你救了我之类的。你是个优秀的得力仆从！");
        add("dialogs.confluence.angler.wakeup.1", "啥？你是哪位？我绝对不是溺水之类的！");
        add("dialogs.confluence.angler.wakeup.2", "你救了我！你太好了，我可以使唤你……呃，我是说，雇你帮我做些了不起的事！");
        add("dialogs.confluence.female_angler.0", "真可惜呀！有些鱼或许在我出生前就消失了，希望能好好保护剩下的它们～");
        add("dialogs.confluence.female_angler.1", "啊……抱歉！是不是打扰到我收钓线了？实在不好意思呀！");
        add("dialogs.confluence.female_angler.2", "整个%s里虽然没有厨师，但能自己亲手烹鱼，也是一种幸福呢！");
        add("dialogs.confluence.female_angler.3", "我没有爸爸妈妈，但有这么多可爱的鱼儿作伴！我已经很满足啦～");
        add("dialogs.confluence.female_angler.4", "听姐姐一句劝哦，千万别用舌头碰冰块啦！会冻伤的，一定要好好照顾自己呀～");
        add("dialogs.confluence.female_angler.5", "你听说过会叫的鱼吗？我好像见过哦，要不要和我聊聊呀！");
        add("dialogs.confluence.female_angler.6", "哎呀！小心一点～我布置了些小装饰，不是陷阱啦，只是想给大家一点小惊喜，千万别误会哦～");
        add("dialogs.confluence.female_angler.7", "%s里到处都是可爱又特别的鱼儿，真的太美好了！");
        add("dialogs.confluence.female_angler.stat.0", "你知道吗？我已经收集到%s条超美的鱼了！真的太谢谢你了，没有你的帮忙我肯定做不到的！");
        add("dialogs.confluence.female_angler.stat.1", "哎呀！麻烦你%s次了，真的太不好意思啦！不过每次都能见到这么好看的鱼，真的太开心了！");
        add("dialogs.confluence.female_angler.wakeup.0", "太感谢你了！真的不知道该怎么报答你，你真的是个超级好的朋友！");
        add("dialogs.confluence.female_angler.wakeup.1", "呀？是你呀～刚刚只是脚滑了一下，不是溺水啦，谢谢你这么关心我！");
        add("dialogs.confluence.female_angler.wakeup.2", "谢谢你救了我！你真的太好了～如果你不介意的话，我想请你帮我做点小事，当然不愿意也没关系的！");
        add("dialogs.confluence.female_angler.task_ready.0", "你好呀～我有个小小的请求，如果你方便的话能不能帮我一下？不方便也完全没关系的！");
        add("dialogs.confluence.female_angler.task_ready.1", "我想找一条特别的鱼，如果你愿意帮忙找找的话就太好啦！不急的，慢慢说细节～");
        add("dialogs.confluence.female_angler.task_ready.2", "%1$s想正式邀请你成为%2$s的钓鱼小帮手，你愿意吗？");
        add("dialogs.confluence.female_angler.task_ready.3", "你好呀！你就是我一直想找的、超厉害的钓鱼大师吧！能请你帮帮忙吗？");
        add("dialogs.confluence.female_angler.task_succeed.0", "哇！谢谢你帮我抓到想要的鱼，真的太感谢了！辛苦你啦～");
        add("dialogs.confluence.female_angler.task_succeed.1", "你真的做得超棒的！辛苦你了，快歇一歇吧～");
        add("dialogs.confluence.female_angler.task_succeed.2", "太开心啦！你安全完成了，真的太好了！我还一直担心你呢！");
        add("dialogs.confluence.female_angler.task_succeed.3", "天呐！？你不仅完成了任务，还平平安安的，真的太棒了！快把鱼给我，快去休息一下吧～");
        add("dialogs.confluence.female_angler.task_succeed.4", "抓到啦！一切都超顺利的～谢谢你的帮忙，真的太感谢了！");
        add("dialogs.confluence.female_angler.task_finished.0", "我的鱼已经足够啦！真的太谢谢你的帮忙，你真的帮了我太多了～");
        add("dialogs.confluence.female_angler.task_finished.1", "今天真的谢谢你啦，和你相处超开心的！你快去忙自己的事吧～");
        add("dialogs.confluence.female_angler.task_finished.2", "暂时没有需要帮忙的啦，不过还是谢谢你愿意过来～");
        add("dialogs.confluence.female_angler.task_finished.3", "今天的鱼已经够啦，辛苦你啦，慢走哦～");
        add("dialogs.confluence.female_angler.task_finished.4", "上次你给我的鱼我还好好收着呢，暂时不需要啦，不过还是超感谢你的！");
        add("dialogs.confluence.female_angler.task_finished.5", "真的太谢谢你啦！能有你这样的帮手，是%s的幸运呀～");
        add("dialogs.confluence.angler.item.confluence.amanita_fungifin", "我在巨大的发光蘑菇中发现了这个惊人的地方！一切都是蓝的！我正在采摘蓝光湖畔的一些蘑菇，其中一只蘑菇突然咬了我一口，然后游走了！我想以其人之道还治其人之身，并狂咬它一顿！我的意思是，你去把它弄回来给我！（抓捕位置：发光蘑菇地）");
        add("dialogs.confluence.angler.item.confluence.angelfish", "你知道吗，天空中漂浮着许多神奇的岛屿？你肯定不知道！他们说，天使住在天上，我相信这些天使都有鳍和鳃，在那游来游去！我相信你肯定能抓一个给我！（抓捕位置：天湖）");
        add("dialogs.confluence.angler.item.confluence.batfish", "呐呐呐呐呐呐呐，蝙蝠鱼！意思是去地下深挖，抓住它，再带来给我！（抓捕位置：地下和洞穴）");
        add("dialogs.confluence.angler.item.confluence.bloody_manowar", "噢！别靠近我！我被一条血水母蜇了！怕你孤陋寡闻不知道血水母是什么，所以我告诉你，它是整个世界中最凶险的水母！如果你敢，去那个烂透了的猩红之地，把它抓来！（抓捕位置：猩红之地）");
        add("dialogs.confluence.angler.item.confluence.bonefish", "如果看到地下水中漂浮着鱼骨，我通常不怎么好奇，但是这只鱼骨竟然在游泳！什么，你以为在世界中还能动的只有人类的骷髅吗？去抓一只给我，这样我可以把它钉在别人的床上！（抓捕位置：地下和洞穴）");
        add("dialogs.confluence.angler.item.confluence.bumblebee_tuna", "在世界的地下丛林中有许多光怪陆离的生物！比如说，我看见过这种鱼，像一只超级大黄蜂！我对蜜蜂过敏，所以你必须去把它给我抓来！它的味道肯定像金枪鱼和蜂蜜三明治！（抓捕位置：蜂蜜）");
        add("dialogs.confluence.angler.item.confluence.bunnyfish", "我正在森林里钓鱼，对吧？你猜发生了什么！一只兔兔朝我跳了过来！然后，又有一只跳过来，又有一只……突然间我就被兔兔包围了！甚至有一只从水里向我游过来，但它没有腿！我惊讶地从椅子上跌下来，把所有兔兔都吓跑了！我想要那条兔兔鱼作为宠物，因此你最好去把它抓来给我！马上！（抓捕位置：地表）");
        add("dialogs.confluence.angler.item.confluence.capn_tunabeard", "哟，朋友！吓本大盗一跳！停船，我的乖乖！有一个海盗船长，养了一条叫“金枪鱼须船长”的宠物鱼，但在一场大风暴中，鱼缸落水了！它有一个尾钩，一个眼罩，还有别的！你需要把那条鱼抓给我，这样我就能像海盗一样酷酷的！显然，它就在大海的某个地方！咄！（抓捕位置：海洋）");
        add("dialogs.confluence.angler.item.confluence.catfish", "我终于找到一只喜欢水的丛林猫！我想这是因为它还有鱼的天性。我不知道为什么会这样，我也不想知道。我只是希望它能到我手里，你得快点！（抓捕位置：丛林地表）");
        add("dialogs.confluence.angler.item.confluence.cloudfish", "有谣言说天上漂浮着岛屿，岛上有惊人的宝藏！但是谁会在意呢，更有意思的是，云彩中有时会形成湖泊，湖泊中游荡着云朵做成的鱼！我想尝尝它的味道，所以你最好去把它抓来给我！（抓捕位置：天湖）");
        add("dialogs.confluence.angler.item.confluence.clownfish", "我在海边看到过这条亮橙色的彩鱼，它在疯狂地游来游去，好像在找走丢的家人！去把它抓来给我，这样又会有一条游出来找它！（抓捕位置：海洋）");
        add("dialogs.confluence.angler.item.confluence.cursedfish", "有条受诅咒的鱼在腐化之地最深处的水中游来游去！它由潜藏在那里的堕落恐怖蔓延出来的诅咒焰化成。他们说，诅咒焰连水都无法扑灭，可以永远燃烧。有一条这样的鱼，我就可以做许多好玩的事！你去抓给我！还是你太胆小！？（抓捕位置：腐化之地）");
        add("dialogs.confluence.angler.item.confluence.demonic_hellfish", "我听说在地狱，所有恶魔的王其实是一条鱼！想象一下，如果你去抓一条给我，我将拥有强大的王权！（抓捕位置：洞穴）");
        add("dialogs.confluence.angler.item.confluence.derpfish", "丛林里的那些跳跳兽是我见过的最可怕的怪物！好的一面是，有时候它们没有腿！这些是生活在水中的，就没那么可怕了！马上去给我抓一只，这样我可以品尝它们的味道，还不会被吓个半死！（抓捕位置：丛林地表）");
        add("dialogs.confluence.angler.item.confluence.dirtfish", "正当我在收线钓起一条大鱼时，这个僵尸从森林湖中蹦出来，不仅很搞笑还会说话，然后开始大说特说这种用土做成的“凶残”的鱼！他说，这鱼能闷死十个像他这个块头的小伙子……我要得到它！马上！（抓捕位置：地表和地下）");
        add("dialogs.confluence.angler.item.confluence.dynamite_fish", "爆破专家在森林里的湖中弄丢了一捆雷管，一直很着急。他有那么多炸药，丢的那捆炸药有这么重要吗？显然，因为这捆炸药长出了鳍，开始游走了！我不知道他做炸药的材料是哪儿弄的，但那一捆肯定已经走火入魔了！钓回来给我，我一直想要一条自杀式炸弹鱼！不要问为什么……（抓捕位置：地表）");
        add("dialogs.confluence.angler.item.confluence.eater_of_plankton", "你肯定不敢去找浮游噬鱼。它是由世界吞噬怪的残块变异而来的腐化鱼！把它抓来给我，证明你不是胆小鬼！（抓捕位置：腐化之地）");
        add("dialogs.confluence.angler.item.confluence.fallen_starfish", "我喜欢收集天上落下来的亮黄色星星！如果落在某个人的脑袋上，我会更喜欢。但是……但是……我最喜欢的还是星星落在森林湖中变成鱼！那条鱼简直酷毙了，而你又这么牛，快去抓来给我！（抓捕位置：天湖和地表）");
        add("dialogs.confluence.angler.item.confluence.the_fish_of_cthulhu", "显然，恶魔眼有时是两栖的。它们不飞，它们游！我想知道有人在浴缸中发现一条时会有怎样的表情！它们总是在同一个区域晃悠。所以，你要钓一条给我！（抓捕位置：天湖和地表）");
        add("dialogs.confluence.angler.item.confluence.fishotron", "我不知道哪种情况更惨：骷髅鱼还是长了手的骷髅鱼。这条深藏在洞穴中的骷髅王鱼真把我吓了一跳！我认为它和地牢边的那个老人被同一个恶魔掌控着！我给你两个胆，你去把它抓来给我！（抓捕位置：洞穴）");
        add("dialogs.confluence.angler.item.confluence.fishron", "有一个名为猪龙鱼的传奇生物！它一部分是猪，一部分是龙，还有一部分是鱼！我听说，它在世界最寒冷的冰封地下湖中游荡！我不会去那里，因此你去抓它，一定要到我的手里！我太激动了！");
        add("dialogs.confluence.angler.item.confluence.guide_voodoo_fish", "地狱的恶魔真的很喜欢巫毒娃娃，但我觉得有一个娃娃身藏着特别多的魔法！它变成了一条鱼，还可以对自己施法。我命令你去地狱，给我带一个来！如果是我的话，我会小心沸腾的熔岩，因为它会把你烧死，这样我就得不到鱼了！（抓捕位置：洞穴）");
        add("dialogs.confluence.angler.item.confluence.harpyfish", "我正要在山上的湖畔睡觉时，这条鱼向我俯冲下来。它在飞！它长着一张女人的脸，还有羽毛！我想我叫得比她还大声！嘿，她把我吓成那样，你去让她付出代价！（抓捕位置：天湖和地表）");
        add("dialogs.confluence.angler.item.confluence.hungerfish", "血肉墙上饿鬼的一块碎片变形成了小鱼一样的东西，在地狱漫无目的地游来游去。它很恶心，但我现在就要！（抓捕位置：洞穴）");
        add("dialogs.confluence.angler.item.confluence.ichorfish", "你知道吗？在猩红之地的深处，一些生物在制作这种恶心的黄东西。我听说一池黄东西融合成鱼形，然后开始游来游去，太离奇了！去抓一条给我，我可以把它塞在别人的马桶里！（抓捕位置：猩红之地）");
        add("dialogs.confluence.angler.item.confluence.infected_scabbardfish", "一条很长的鱼，看起来像剑鞘，在腐化之地的浑水中游来游去！它看起来很像黑檀石，所以不要让它骗了你！没错，就你啦。你去抓它，而不是我去！（抓捕位置：腐化之地）");
        add("dialogs.confluence.angler.item.confluence.jewelfish", "哦哦，我马上就要发大财啦！在洞穴的深处，有一种宝石做的鱼！别问我怎么做，我不知道，我知道的是，这种鱼非常美丽，你去把它抓来给我！（抓捕位置：地下和洞穴）");
        add("dialogs.confluence.angler.item.confluence.mirage_fish", "我告诉你，在地下更深处的神圣之地里可以找到一些有趣的小动物！它们闪耀着疯狂的紫色，让我眼花缭乱！这鱼是绝对狂野的，因此我希望你能抓一条给我！（抓捕位置：地下神圣之地）");
        add("dialogs.confluence.angler.item.confluence.mudfish", "经过丛林的水域时，要注意脚下！为什么？不，我不担心你会被食人鱼吃掉。我担心你会踩到我最喜欢的一种鱼，泥鱼！我还希望，你会抓一条来给我当宠物！（抓捕位置：丛林）");
        add("dialogs.confluence.angler.item.confluence.mutant_flinxfin", "棕白色、毛茸茸，住在冰冻地下湖中，是什么鱼？突变雪怪鱼！我没有开玩笑，确实有一种更适应水生生活的突变雪怪鱼！我希望它能够适应我的鱼缸，一定要抓一条！（抓捕位置：地下苔原）");
        add("dialogs.confluence.angler.item.confluence.pengfish", "是鲸鱼！是海豚！不，是企鹅鱼！瞧瞧，该你出马了！你去给我抓一条！你知道它们只喜欢冷水吧？（抓捕位置：地表苔原）");
        add("dialogs.confluence.angler.item.confluence.pixiefish", "有一种十分十分罕见的妖精，长了太多翅膀，所以完全飞不起来！它在蓝色草地环绕的湖中与鱼儿一起游来游去。我的鱼缸需要一盏灯，所以我想让你把那个妖精抓来给我！（抓捕位置：地表神圣之地）");
        add("dialogs.confluence.angler.item.confluence.scarab_fish", "我读过这个古老的故事，讲的是一条长得像魔法金龟子的鱼！说白了就是甲虫！在哪里能找到它？你说呢？咄，在沙漠！别那样看着我……是真的！那里其实是有水的！我想去，但我怕我的眼珠子被秃鹰啄掉。所以……还是你去吧！（抓捕位置：沙漠）");
        add("dialogs.confluence.angler.item.confluence.scorpio_fish", "我敢肯定有人告诉过你沙漠里没有水，真是愚蠢至极！大错特错！沙漠里有种叫绿洲的地方，那里就有水！你说有水就会有什么！？没错，有鱼！那些奇怪的鱼会叮你、咬你，用尽各种方法折磨你！这是一种很适合我的宠物，也是一个很适合你的任务！（抓捕位置：沙漠）");
        add("dialogs.confluence.angler.item.confluence.slimefish", "森林里的史莱姆有点恶心。史莱姆鱼更恶心！我可不想与史莱姆们一起游泳，所以你快去从水里抓一条给我！（抓捕位置：地表森林）");
        add("dialogs.confluence.angler.item.confluence.spiderfish", "我看到一条八条腿的鱼！不！不可能！你为我钓它，这样它到我手里时就是死的了！这是我最后一次去这么深的洞穴钓鱼！（抓捕位置：地下和洞穴）");
        add("dialogs.confluence.angler.item.confluence.tropical_barracuda", "食人鱼和鲨鱼都很丑！太太太丑了！你知道吗？有一种鱼长得很漂亮，但可以把你的脸咬掉。顺便说，我愿意付两铂金币来让这事发生。不过关键是，你要抓一条给我。一定要在你的脸被咬掉之前，把它交给我！（抓捕位置：丛林地表）");
        add("dialogs.confluence.angler.item.confluence.tundra_trout", "你知道位于世界雪域表面上的湖泊为什么从不结冰吗？我不知道。但鱼知道！用冰制成的鱼会作为上佳的祭品进贡给伟大且神奇的渔夫！去吧，我的忠诚仆人，赶快把这条苔原鳟鱼带给我！（抓捕位置：地表苔原）");
        add("dialogs.confluence.angler.item.confluence.unicorn_fish", "独角兽和彩虹都是好东西！它们无处不在，甚至在水中。真的，我居然在圣湖中看到一条独角兽鱼！你的任务就是把它钓起来，我会拿它当宠物！（抓捕位置：神圣之地）");
        add("dialogs.confluence.angler.item.confluence.wyverntail", "我知道一些你……你不知道的事！好吧，我告诉你，有一只可怕的怪物在星空中飞来飞去！这不是我自己编出来的！它叫飞龙！可是，可是，你已经知道了，是不是？你不知道的是，它们就像蝌蚪那样出生和成长！所以，它们实际上像……像青蛙！开始行动，给我抓一只！（抓捕位置：天湖）");
        add("dialogs.confluence.angler.item.confluence.zombie_fish", "你相信吗？！我晚上在森林里抓到一条已经死了的鱼！然后，它想吃我！我把它扔掉，然后扭头就跑！现在，我要把它钉在别人的梳妆台上，看看会发生什么，所以你去把那条鱼给我抓回来，好吗？！（抓捕位置：地表）");

        add("dialogs.confluence.guide.0", "我的工作是为你接下来的任务提供建议。建议你遇到任何困难时都来和我谈谈。");
        add("dialogs.confluence.guide.1", "他们说，有个人会告诉你如何在这地方上生存……哦等下。那个人就是我。");
        add("dialogs.confluence.guide.2", "晚上你应该呆在家里。黑夜在外面转悠非常危险。");
        add("dialogs.confluence.guide.3", "在融合的世界中，你会收获多倍的宝藏，但这也以为着承担多倍的风险。");
        add("dialogs.confluence.guide.4", "据我所知这个世界上的人类比我们原来的世界更多。");
        add("dialogs.confluence.guide.5", "抱歉，有时候我不得不开门。");
        add("dialogs.confluence.guide.6", "那些会爆炸的家伙比一般的地表怪物更具威胁！");
        add("dialogs.confluence.guide.7", "草地上的生命蘑菇有时候可以救你一命。");
        add("dialogs.confluence.guide.8", "地下有水晶之心，可以用来提高你的最大生命值。你可以用镐来打碎它们。");
        add("dialogs.confluence.guide.9", "地底下有一种具有神奇魔力的湖，它非常稀有。");
        add("dialogs.confluence.guide.10", "夜晚，星星在坠落，洒满全世界。它们的用途极为广泛。如果你看到了，一定要拿到手，因为星星在日出后就会消失。");
        add("dialogs.confluence.nurse.0", "我要和向导认真谈一谈。你一周到底有多少次被熔岩烫成重伤？");
        add("dialogs.confluence.nurse.1", "看到那个在地牢周围转来转去的老人没？他看上去遇到麻烦了。");
        add("dialogs.confluence.nurse.2", "嗨，军火商有没有提过要去看医生啥的？就随便问问。");
        add("dialogs.confluence.nurse.3", "又惹上混混了？");
        add("dialogs.confluence.nurse.4", "别像个孩子似的！我见过更糟的。");
        add("dialogs.confluence.nurse.5", "你这么做的时候疼吗？别那么做。");
        add("dialogs.confluence.demolitionist.0", "炸药如今十分火爆。马上买一些！");
        add("dialogs.confluence.demolitionist.1", "今天是个找死的好日子！");
        add("dialogs.confluence.demolitionist.2", "让我看看这样会怎……（轰！）……哦，对不起，你还要那条腿吗？");
        add("dialogs.confluence.demolitionist.3", "看看我的商品；都是惊爆价");
        add("dialogs.confluence.demolitionist.4", "雷管，这是我特别为你准备的灵丹妙药，包治百病。");
        add("dialogs.confluence.demolitionist.5", "想穿过那些邪恶石头，嗯？为什么不用炸药炸掉它！");
        add("dialogs.confluence.goblin_tinkerer.0", "哥布林太容易生气了。事实上，他们能为了一些破布发动战争！");
        add("dialogs.confluence.goblin_tinkerer.1", "老实说，大部分哥布林都不是真正的火箭科学家。好吧，有一些是。");
        add("dialogs.confluence.goblin_tinkerer.2", "你知不知道为什么大家到哪儿都带着这些尖刺球？因为我不知道。");
        add("dialogs.confluence.goblin_tinkerer.3", "我刚刚完成了最新的作品！这个版本就算你对着它猛力吹吸也不会猛烈爆炸。");
        add("dialogs.confluence.goblin_tinkerer.4", "哥布林盗贼不太擅长偷东西。没上锁的箱子都不会偷！");
        add("dialogs.confluence.goblin_tinkerer.5", "唷，我听说你喜欢火箭和跑鞋，所以我在你的跑鞋上加了一些火箭。");
        add("dialogs.confluence.arms_dealer.0", "哥们，把手从我的枪上拿开！");
        add("dialogs.confluence.arms_dealer.1", "嘿，兄弟，这可不是演电影。需要另行准备弹药。");
        add("dialogs.confluence.arms_dealer.2", "我看你在盯着迷你鲨……你绝对想不到它是怎么做成的。");
        add("dialogs.confluence.arms_dealer.3", "我想买护士卖的东西。你说啥？她什么也不卖？");
        add("dialogs.confluence.arms_dealer.4", "飞鱼？我把它叫作打靶！");
        add("dialogs.confluence.arms_dealer.5", "别和爆破专家浪费时间了。我这边有你要的一切。");
        add("dialogs.confluence.merchant.0", "剑克纸！赶紧买一把。");
        add("dialogs.confluence.merchant.1", "你想要苹果？你想要胡萝卜？你想要菠萝？我们只有火把。");
        add("dialogs.confluence.merchant.2", "看看我的土块；它们特别土。");
        add("dialogs.confluence.merchant.3", "你是不知道土块能在国外卖多少钱。");
        add("dialogs.confluence.merchant.4", "总有一天他们会讲述你的传奇……肯定会是好故事。");
        add("dialogs.confluence.merchant.5", "Kosh, kapleck Mog。哦，对不起，这是克林贡语，意思是“要么买，要么死。”");
        add("dialogs.confluence.painter.0", "我知道青绿色和蓝绿色之间的差别。但我不会告诉你。");
        add("dialogs.confluence.painter.1", "钛白色用完了，别问了。");
        add("dialogs.confluence.painter.2", "尝试调合粉色和紫色，肯定管用，我发誓！");
        add("dialogs.confluence.painter.3", "不、不、不……灰色也分很多种！别让我开始……");
        add("dialogs.confluence.painter.4", "我希望别下雨了，漆还没干。下雨就惨了！");
        add("dialogs.confluence.painter.5", "我试过举办一次彩弹大战，但是每个人都只想要食物和装饰品。");
        add("dialogs.confluence.dryad.0", "注意安全！两边的世界都需要你！");
        add("dialogs.confluence.dryad.1", "时间的沙漏在缓缓流逝。而你并没有优雅地变老。");
        add("dialogs.confluence.dryad.2", "两个哥布林走进酒吧，其中一个对另一个说：“来杯啤酒？！");
        add("dialogs.confluence.dryad.3", "说我雷声大雨点小是啥意思？");
        add("dialogs.confluence.dryad.4", "你必须停止邪恶的蔓延。");
        add("dialogs.confluence.dryad.5", "这个世界更为广阔……自然的力量也更强大了");
        add("dialogs.confluence.dye_trader.0", "我带给你最丰富的色彩，以换取你的财富。");
        add("dialogs.confluence.dye_trader.1", "亲爱的，你的穿着太单调了。你一定得好好学学，怎么给单调的衣服染色！");
        add("dialogs.confluence.dye_trader.2", "我唯一愿意染的木材是红木。给任何其他木材染色都是浪费。");
        add("dialogs.confluence.dye_trader.3", "噢，不行，不行，这样是不行的。有钱也没用，你必须拿稀有的植物样本来和我交换！");
        add("dialogs.confluence.dye_trader.4", "这些染料瓶？抱歉，亲爱的朋友，这些是非卖品。我只接受用最珍稀的植物来交换它们！");
        add("dialogs.confluence.dye_trader.5", "你以为可以骗过我的眼睛？我可不这么想！我只接受用最稀有的花来交换这些特别的瓶子。");
        add("dialogs.confluence.angler.0", "太可气了！有些鱼可能在我出生之前就灭绝了，真不公平！");
        add("dialogs.confluence.angler.1", "什……么？！难道你没看见我在收钓鱼线吗？？");
        add("dialogs.confluence.angler.2", "整个%s中都没有厨师，所以我不得不自己烹鱼！");
        add("dialogs.confluence.angler.3", "我没有妈妈，也没有爸爸，但我有很多鱼！这就够了！");
        add("dialogs.confluence.angler.4", "听听小孩的忠告吧，永远不要用舌头碰冰块！等一下，就当我没说，我就想看你这样做！");
        add("dialogs.confluence.angler.5", "听说过会叫的鱼吗？！我没听说过，只是想知道你听说过没！");
        add("dialogs.confluence.old_man.0", "如果你不解除我的诅咒，我是不会让你进的。");
        add("dialogs.confluence.old_man.1", "陌生人，你是否拥有能打败我主人的力量？");
        add("dialogs.confluence.old_man.2", "打败我的主人，我就让你进入地牢。");
        add("dialogs.confluence.old_man.3", "你要想进去的话就晚上再来。");
        add("dialogs.confluence.traveling_merchant.0", "嗯，看上去你会使用天使雕像！他们切片，又切丁，让一切都如此美好！");
        add("dialogs.confluence.traveling_merchant.1", "我不会因“买家后悔……”或者任何其它原因退款，绝不退。");
        add("dialogs.confluence.traveling_merchant.2", "现在购买还包邮！");
        add("dialogs.confluence.traveling_merchant.3", "我卖的商品来自可能根本就不存在的地方！");
        add("dialogs.confluence.traveling_merchant.4", "你想要两文钱！？一文钱就成交。");
        add("dialogs.confluence.traveling_merchant.5", "既能抽水烟，也能煮咖啡！还能炸切丝薯条！");
        add("dialogs.confluence.traveling_merchant.6", "看一看，瞧一瞧！一斤重的鱼！新鲜味美！一斤重的鱼！");
        add("dialogs.confluence.traveling_merchant.7", "如果你是在找垃圾，那就来错地方了。");
        add("dialogs.confluence.traveling_merchant.8", "旧货店？不，我只卖市场上的尖货。");
        add("dialogs.confluence.mechanic.0", "你确定你的设备插好电源了？");
        add("dialogs.confluence.mechanic.1", "哦，你知道这个房屋需要什么？需要更多的闪光信号灯。");
        add("dialogs.confluence.mechanic.2", "别动。我的隐形眼镜掉了。");
        add("dialogs.confluence.mechanic.3", "谢谢！迟早有一天，我的结局也会和地牢里的其他骷髅一样。");
        add("dialogs.confluence.mechanic.4", "我记不太清楚里面发生过什么了，三个还是四个很重要的东西...");
        add("dialogs.confluence.mechanic.5", "噢是的，信号适配器！它可以很好地把这里的红石和电线连接起来。");
        add("dialogs.confluence.witch_doctor.0", "我是啥医？我是巫医。");
        add("dialogs.confluence.witch_doctor.1", "认真选，我的商品不稳定，我的黑魔法很神秘。");
        add("dialogs.confluence.witch_doctor.2", "魔法的心脏是本质。心脏的本质是魔法。");
        add("dialogs.confluence.witch_doctor.3", "我感觉与埃特尼亚黑暗魔法师志趣相投。可惜他们是我们的敌人，我本来希望向他们学习来着。");
        add("dialogs.confluence.clothier.0", "再次感谢你帮我解了诅咒。感觉像是什么东西跳起来咬了我一口。");
        add("dialogs.confluence.clothier.1", "妈妈总是说我会成为一位伟大的裁缝。");
        add("dialogs.confluence.clothier.2", "生活就像一箱衣服；你永远也不知道自己要穿什么！");
        add("dialogs.confluence.clothier.3", "刺绣当然难了！如果不难，就没人绣了！所以刺绣是件难能可贵的事。");
        add("dialogs.confluence.clothier.4", "他们想了解服装行业，而我无所不知。");
        add("dialogs.confluence.clothier.5", "被诅咒后很孤独，于是我用皮革制作了一个朋友。我叫他威尔森。");
        add("dialogs.confluence.clothier.6", "我依稀记得把一个女人捆了起来，然后扔到了地牢里。");
        add("dialogs.confluence.party_girl.0", "我们得谈谈。这……聚会的事。");
        add("dialogs.confluence.party_girl.1", "我不知道我是更喜欢派对还是余兴派对。");
        add("dialogs.confluence.party_girl.2", "我们应该办一个闪耀根派对，而且我们还应该办一个余兴派对。");
        add("dialogs.confluence.party_girl.3", "装个迪斯科球，我会让你知道怎么开派对。");
        add("dialogs.confluence.party_girl.4", "我去过一次瑞典，他们经常开派对，你怎么和他们不一样？");
        add("dialogs.confluence.party_girl.5", "我叫派对女孩，但人们叫我派对扫把星。我也搞不懂为啥这样叫我，但听起来酷酷的。");
        add("dialogs.confluence.party_girl.6", "你开派对吗？有时开？好吧，那我们谈谈……");
        add("dialogs.confluence.truffle.0", "生活在地下已经够惨的了，像你这样的败类还要趁我睡觉来偷我的孩子。");
        add("dialogs.confluence.truffle.1", "有一天，我试着舔了舔自己，看看会发生什么大不了的事，然后全身都开始发蓝光。");
        add("dialogs.confluence.truffle.2", "每次看到蓝色，我都感到郁闷和懒散。");
        add("dialogs.confluence.truffle.3", "你在这附近看到过猪吗？我弟弟的一条腿被猪叼走了。");
        add("dialogs.confluence.truffle.4", "我不知道什么是“肚皮波浪”，所以别问了！");
        add("dialogs.confluence.truffle.5", "有个关于我的谣言正在盛传：“如果打不过他，那就吃掉他！");
        add("dialogs.confluence.truffle.6", "我感觉这里有更多同类...");
        add("dialogs.confluence.guide.jei_check", "在Minecraft里，我帮不到你查询配方，但是我知道一个叫JEI的模组可以帮到你。");
        add("dialogs.confluence.nurse.player_killed_by", "你已经被%1$s杀死%2$s次了？我很好奇是谁拿走了你的旗子。");

        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.0", "咱们再去砍棵树吧！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.1", "这真是太棒了！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.2", "去死！去死！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.3", "我活着就是为了这个！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.4", "愚蠢的树！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.5", "我活力四射！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.6", "我们成功了！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.7", "哈哈哈！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.8", "哇哦！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_tree.9", "太好了！");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_gem_tree.0", "所以，石头树……那是怎么回事？");
        add("dialogs.confluence.lucy_the_axe.cutting_down_a_cactus.0", "你想想看，仙人掌就是带刺的树而已！");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.0", "真是糟透了。");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.1", "这里好黑！");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.2", "救命！快把我弄出去！");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.3", "这里没什么可砍的！");
        add("dialogs.confluence.lucy_the_axe.placed_in_other_container.4", "我有幽闭恐惧症！");
        add("dialogs.confluence.lucy_the_axe.placed_back_into_the_inventory.0", "哦，谢天谢地！");
        add("dialogs.confluence.lucy_the_axe.placed_back_into_the_inventory.1", "从现在开始，我们形影不离。");
        add("dialogs.confluence.lucy_the_axe.placed_back_into_the_inventory.2", "啊，我回到了我该待的地方。");
        add("dialogs.confluence.lucy_the_axe.idle.0", "嘿！砍些树吧！");
        add("dialogs.confluence.lucy_the_axe.idle.1", "今天的天气非常适合砍树。");
        add("dialogs.confluence.lucy_the_axe.idle.2", "砍砍砍。嘿嘿。");
        add("dialogs.confluence.lucy_the_axe.idle.3", "我们合作得很好！");
        add("dialogs.confluence.lucy_the_axe.idle.4", "咱们找片小树林疯砍一通吧！");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.0", "你会回来的对吧？");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.1", "嘿！我绝对不会丢下你的！");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.2", "别把我给忘了！");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.3", "我们不是朋友吗？");
        add("dialogs.confluence.lucy_the_axe.throw_on_the_ground.4", "你要抛弃我？！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.0", "踢掉它！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.1", "太没礼貌了！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.2", "我是把中邪的斧头！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.3", "挑个和你相配的对手！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.4", "喂！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.5", "噢痛，那很痛。");
        add("dialogs.confluence.lucy_the_axe.attack_entity.6", "干掉它们！我被吓死了。");
        add("dialogs.confluence.lucy_the_axe.attack_entity.7", "这就是我生存的目的！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.8", "哇哈哈！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.9", "吼！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.10", "去死！去死！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.11", "漂亮的一斧！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.12", "太棒了！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.13", "我们是一对好搭档！");
        add("dialogs.confluence.lucy_the_axe.attack_entity.14", "别烦我，你这个禽兽！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.0", "哦，太对了！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.1", "多汁！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.2", "一顿满足！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.3", "太值了！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.4", "漂亮！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.5", "令人高兴！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.6", "我很满足！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.7", "狼吞虎咽！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.8", "我为我们感到骄傲！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.9", "就这？");
        add("dialogs.confluence.lucy_the_axe.kill_entity.10", "斧头力量！！！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.11", "太简单了！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.12", "砍得好！");
        add("dialogs.confluence.lucy_the_axe.kill_entity.13", "你是个砍客！");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.0", "我有点受到侮辱。");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.1", "这真没劲。");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.2", "我更喜欢更树的品种。");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.3", "你变了！");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.4", "还记得我们砍树的乐事吗？");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.5", "喂！砍一些树！");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.6", "只工作不娱乐让我想砍更多的树。");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.7", "你知道砍的意思吗？");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.8", "这里面没有一样能砍的东西！");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.9", "这真是最糟糕的情况。");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.10", "我身上都脏了！");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.11", "你怎么敢如此对我！");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.12", "哦，我会记住那的！");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.13", "你不需要这样！");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.14", "你确定你还好吗？");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.15", "今天你看起来特别粗暴。");
        add("dialogs.confluence.lucy_the_axe.destroy_wrong_block.16", "太过分了！");
        add("dialogs.confluence.wizard.0", "想让我从你耳朵后面掏出一个钱币吗？不想？好吧。");
        add("dialogs.confluence.wizard.1", "想要一些魔法糖果吗？不想？好吧。");
        add("dialogs.confluence.wizard.2", "我做了一杯诱人的热巧克力，你感不感……不感兴趣？好吧。");
        add("dialogs.confluence.wizard.3", "你来这里是不是想看看我的水晶球？");
        add("dialogs.confluence.wizard.4", "想不想要可以把石头变成史莱姆的魔戒？好吧，我也不想要。");
        add("dialogs.confluence.wizard.5", "有人曾告诉我友谊是魔法。太荒谬了。你无法用友谊把人变成青蛙。");
        add("dialogs.confluence.wizard.6", "我现在能看到你的未来……你会从我这里买很多物品！");
        add("dialogs.confluence.wizard.7", "我曾经试过复活一座天使雕像。它啥都不干。");
        add("dialogs.confluence.zoologist.0", "我以前也像你一样养小动物，后来被一只受诅咒的狐狸咬到了膝盖！");
        add("dialogs.confluence.zoologist.1", "我可能学识浅薄……但有关自然、小动物、动物和野生动物之类的话题，我可以给你说上三天三夜……");
        add("dialogs.confluence.zoologist.2", "我老哥叫我兽化人。意思是我有一半像动物什么的。不过他都懂，毕竟他常年在外！");
        add("dialogs.confluence.zoologist.3", "我非常喜欢动物！有一次我试着抚摸这只长相奇特的狐狸，他竟然咬了我一口，现在我变成了一只动物！酷毙了！");
        add("dialogs.confluence.zoologist.4", "别拉扯我的尾巴了，兄弟，是货真价实的……这样拉扯，我很疼的！");
        add("dialogs.confluence.zoologist.5", "噢，这两只大耳朵吗？哈哈，是用来听你的，宝贝！");
        add("dialogs.confluence.zoologist.6", "这次是在小动物营地，有天早上我醒来，发现一切全变样了！发生这么大的事情，我竟然还睡得着？！");
        add("dialogs.confluence.zoologist.7", "哇，我好像从来没见过满月。不知道为什么，一要出现满月我就会昏倒！");
        add("dialogs.confluence.zoologist.8", "我不知道我是怎么来到这里的，但这感觉太棒了。");
        add("dialogs.confluence.stylist.0", "你的发型还算过得去，不过我能让它变得惊艳。");
        add("dialogs.confluence.stylist.1", "换个新造型，就连冒险者也能显得体面些。");
        add("dialogs.confluence.stylist.2", "坐稳了。好发型需要精准的手艺。");
        add("dialogs.confluence.tax_collector.0", "该交税了。我向你保证，每一枚钱币都记得清清楚楚。");
        add("dialogs.confluence.tax_collector.1", "维持城镇可不便宜。幸运的是，账单由其他人来付。");
        add("dialogs.confluence.tax_collector.2", "又是新的一天，账本里还是写满了欠款。");
    }

    @Override
    public void add(String key, String value) {
        consumer.accept(key, value);
    }
}
